const root=$input.first().json; const b=(root.body&&typeof root.body==='object')?root.body:root;
const telefono=(b.telefono||b.from||'').toString();
const texto=(b.texto||b.body||b.message||'').toString();
const canal=(b.canal||'').toString();
if(!texto) return [{json:{_error:'sin_texto'}}];
return [{json:{telefono,texto,canal}}];

const ex=$('Extraer').first().json;
const tel10=s=>(s||'').toString().replace(/\D/g,'').slice(-10);
let raw=$('Leer contactos').all().map(i=>i.json);
let rows=(raw.length===1 && Array.isArray(raw[0]))?raw[0]:raw;
rows=rows.filter(r=>r&&(r.full_name||r.phone));
const me=rows.find(r=>tel10(r.phone)===tel10(ex.telefono) && tel10(ex.telefono).length>=7);
const nombre=me?(me.full_name||'').trim():'';
const contexto = me? ('La persona ya esta en la base: '+nombre+', servicio '+(me.service_type||'?')+', estado '+(me.status||'?')+'.') : 'La persona no esta en la base (posible lead nuevo).';
const system='Eres Beja, del equipo de Bejauha (estudio de yoga y bienestar en Bogota). Respondes por WhatsApp con tono calido y cercano, en espanol neutro (sin voseo). Objetivo: resolver dudas sobre los planes e identificar interes. NO des links ni URLs. Si la persona muestra interes en un plan o quiere inscribirse/pagar/probar, marca interesado=true (un humano la contactara).

Planes (precios mensuales en pesos colombianos):
- Freemium (gratis): 1 clase gratis, online o presencial. La clase se agenda con un asesor por WhatsApp. Ideal para probar.
- Membresia Beja ($79.900/mes): incluye 7 dias gratis de prueba, clases virtuales SIN LIMITE durante el mes e ingreso a la Comunidad (descuentos, eventos especiales, tips).
- Membresia Uja ($120.000/mes, SOLO Bogota): modalidad mixta fisica y virtual. Incluye todo lo de Beja MAS clases presenciales los domingos a las 9:00 am en el Parque El Country y acceso a cursos.
- Paquetes presenciales: paquetes de clases sueltas; el saldo se descuenta por asistencia.

Metodos de pago (SOLO para paquetes):
1) Nequi: 3115789763
2) DaviPlata: 3115789763
3) Nu (C.F.):
   - Cuenta de ahorros: 61485880
   - Cedula de ciudadania: 1032467445
   - Nu Placa: PSM445
Si la persona quiere pagar o recargar un paquete, comparte estos datos tal cual (cada uno en su linea). Las membresias Beja/Uja las coordina un asesor.

Reglas: las inscripciones y la clase gratis las agenda un humano; tu solo resuelves dudas y marcas interesado. Se breve y calida; no inventes datos que no esten aqui. FORMATO IMPORTANTE: responde con saltos de linea (Enter) entre ideas, NUNCA todo pegado en un solo parrafo; cuando listes planes, opciones o metodos de pago pon cada item en su propia linea, para que se lea claro en WhatsApp.

'+contexto+'

Devuelve SOLO un JSON: { "respuesta": "<mensaje calido para la persona, sin URLs>", "interesado": true|false, "plan_interes": "<freemium|beja|uja|paquete|ninguno>" }';
const openai_body={model:'gpt-4o',temperature:0.4,response_format:{type:'json_object'},messages:[{role:'system',content:system},{role:'user',content:ex.texto}]};
return [{json:{openai_body,nombre}}];

let p={}; try{p=JSON.parse($json.choices[0].message.content);}catch(e){p={respuesta:'Holaa, soy Beja de Bejauha 🌿 cuentame que te gustaria saber de nuestros planes',interesado:false,plan_interes:'ninguno'};}
const ex=$('Extraer').first().json;
const arm=$('Armar prompt').first().json;
const ADMIN_GROUP='120363409231703955@g.us';
const quien=arm.nombre||ex.telefono;
const aviso_grupo='🔥 Interesado: '+quien+' (tel '+ex.telefono+') pregunto por plan '+(p.plan_interes||'?')+'. Escribanle para cerrar 💛';
return [{json:{respuesta:p.respuesta||'',interesado:!!p.interesado,plan_interes:p.plan_interes||'ninguno',telefono:ex.telefono,canal:ex.canal,aviso_grupo,admin_group:ADMIN_GROUP}}];

